        sqlx::Error::RowNotFound => Error::NotFound,
        sqlx::Error::PoolTimedOut => Error::Timeout,
        sqlx::Error::Database(db) => {
            // "UNIQUE constraint failed: user.email" gives the constraint "user.email"

